            return 400
        if doc_id in self.store:
            return 409
        self.store[doc_id] = {'body': body, 'archived': False}
        return 201

    def read(self, doc_id):
        if not isinstance(doc_id, str) or '/' in doc_id or '..' in doc_id:
            return 400
        if doc_id in self.store:
            doc = self.store[doc_id]
            return (200, doc['body']) if not doc['archived'] else (200, None)
        return (404, None)

    def put(self, doc_id, body):
        if not isinstance(doc_id, str) or '/' in doc_id or '..' in doc_id:
            return 400
        if doc_id not in self.store:
            return 404
        if self.store[doc_id]['archived']:
            return 409
        self.store[doc_id]['body'] = body
        return 200

    def archive(self, doc_id):
        if not isinstance(doc_id, str) or '/' in doc_id or '..' in doc_id:
            return 400
        if doc_id not in self.store:
            return 404
        self.store[doc_id]['archived'] = True
        return 200

    def list(self):
        return sorted(self.store.keys())
