def test_create(make):
    store = make()
    assert store.create('doc1', 'body1') == 201
    assert store.create('doc1', 'body1') == 409
    assert store.create('doc2', 'body2') == 201
    assert store.read('doc1')[0] == 200
    assert store.read('doc2')[0] == 200
    assert store.read('doc3')[0] == 404

def test_read(make):
    store = make()
    store.create('doc1', 'body1')
    assert store.read('doc1')[0] == 200
    assert store.read('doc1')[1] == 'body1'
    assert store.read('doc2')[0] == 404
    assert store.read(123)[0] == 400

def test_put(make):
    store = make()
    store.create('doc1', 'body1')
    assert store.put('doc1', 'new_body') == 200
    assert store.read('doc1')[1] == 'new_body'
    assert store.put('doc2', 'body2') == 404
    assert store.put(123, 'body3') == 400
    store.archive('doc1')
    assert store.put('doc1', 'new_body') == 409

def test_archive(make):
    store = make()
    store.create('doc1', 'body1')
    assert store.archive('doc1') == 200
    assert store.read('doc1')[0] == 200
    assert store.read('doc1')[1] == 'body1'
    assert store.archive('doc1') == 404
    assert store.archive(123) == 400

def test_list(make):
