    store.create('doc2', 'body2')
    store.create('doc1', 'body1')
    assert store.list() == ['doc1', 'doc2']
    store.archive('doc1')
    assert store.list() == ['doc1', 'doc2']
    store.create('doc3', 'body3')
    assert store.list() == ['doc1', 'doc2', 'doc3']
