    def __init__(self):
        self.store = {}
        self.archived = {}

    def is_valid_id(self, doc_id):
        return isinstance(doc_id, str) and '/' not in doc_id and '..' not in doc_id

    def create(self, doc_id, body):
        if not self.is_valid_id(doc_id):
            return 400
        if doc_id in self.store or doc_id in self.archived:
            return 409
        self.store[doc_id] = body
        return 201

    def read(self, doc_id):
        if not self.is_valid_id(doc_id):
            return 400
        if doc_id in self.store:
            return 200, self.store[doc_id]
        elif doc_id in self.archived:
            return 200, self.archived[doc_id]
        return 404, None

    def put(self, doc_id, body):
        if not self.is_valid_id(doc_id):
            return 400
        if doc_id in self.archived:
            self.archived[doc_id] = body
        elif doc_id in self.store:
            self.store[doc_id] = body
        else:
            return 404
        return 200

    def archive(self, doc_id):
        if not self.is_valid_id(doc_id):
            return 400
        if doc_id in self.store:
            self.archived[doc_id] = self.store.pop(doc_id)
        elif doc_id in self.archived:
            return 200
        return 404

    def list(self):
        return sorted(self.store.keys() + self.archived.keys())
